    test("appsRevertRollback answers 401 with its declared error body", () async {
      SdkConfig.getConfig().baseUrl = '$baseUrl/__mockStatus/401';
      addTearDown(() => SdkConfig.getConfig().baseUrl = baseUrl);
      final SdkHttpError error;
      try {
        await sdk_methods_5.appsRevertRollback(
        config,
        appId: (jsonDecode("\"4f6c71e2-1e90-4762-9fee-6cc4a0a9f2cf\"") as String),
      );
        fail('did not raise its declared error');
      } on SdkHttpError catch (caught) {
        error = caught;
      }
      expect(error.statusCode, 401);
      expect(
        mismatch(normal(error.data), SdkUtils.decodeJson("{\"id\":\"unauthorized\",\"message\":\"Unable to authenticate you.\"}")),
        isNull,
      );
    });

