    test("genaiCancelModelEvaluationRun answers 401 with its declared error body", () async {
      SdkConfig.getConfig().baseUrl = '$baseUrl/__mockStatus/401';
      addTearDown(() => SdkConfig.getConfig().baseUrl = baseUrl);
      final SdkHttpError error;
      try {
        await sdk_methods_22.genaiCancelModelEvaluationRun(
        config,
        evalRunUuid: (jsonDecode("\"\\\"123e4567-e89b-12d3-a456-426614174000\\\"\"") as String),
        evalRunUuid_2: SdkPresent<String>((jsonDecode("\"\\\"12345678-1234-1234-1234-123456789012\\\"\"") as String)),
      );
        fail('did not raise its declared error');
      } on SdkHttpError catch (caught) {
        error = caught;
      }
      expect(error.statusCode, 401);
      expect(
        mismatch(normal(error.data), SdkUtils.decodeJson("{\"id\":\"unauthorized\",\"message\":\"Unable to authenticate you.\"}")),
        isNull,
      );
    });

