    test("genaiGetWorkspace answers 401 with its declared error body", () async {
      SdkConfig.getConfig().baseUrl = '$baseUrl/__mockStatus/401';
      addTearDown(() => SdkConfig.getConfig().baseUrl = baseUrl);
      final SdkHttpError error;
      try {
        await sdk_methods_22.genaiGetWorkspace(
        config,
        workspaceUuid: (jsonDecode("\"\\\"123e4567-e89b-12d3-a456-426614174000\\\"\"") as String),
      );
        fail('did not raise its declared error');
      } on SdkHttpError catch (caught) {
        error = caught;
      }
      expect(error.statusCode, 401);
      expect(
        mismatch(normal(error.data), SdkUtils.decodeJson("{\"id\":\"unauthorized\",\"message\":\"Unable to authenticate you.\"}")),
        isNull,
      );
    });

    test("genaiImportCustomModel reaches the mock and decodes its response", () async {
      final actual = await sdk_methods_22.genaiImportCustomModel(
        config,
        acceptHfTokenStorage: SdkPresent<bool>((jsonDecode("true") as bool)),
        acceptTermsAndConditions: SdkPresent<bool>((jsonDecode("true") as bool)),
        description: SdkPresent<String>((jsonDecode("\"Production model for customer support\"") as String)),
        name: SdkPresent<String>((jsonDecode("\"my-mistral-7b\"") as String)),
        preferredGpuRegion: SdkPresent<String>((jsonDecode("\"nyc3\"") as String)),
        sourceRef: SdkPresent<CustomModelSourceRef>(CustomModelSourceRef.fromJson((jsonDecode("{\"access_type\":\"ACCESS_TYPE_UNSPECIFIED\",\"bucket\":\"example string\",\"commit_sha\":\"example string\",\"hf_token\":\"example string\",\"prefix\":\"example string\",\"region\":\"example string\",\"repo_id\":\"123e4567-e89b-12d3-a456-426614174000\"}") as Map).cast<String, dynamic>())),
        sourceType: SdkPresent<CustomModelSourceType>(CustomModelSourceType.fromJson(jsonDecode("\"SOURCE_TYPE_UNSPECIFIED\"") as String)),
        tags: SdkPresent<CustomModelTags>(CustomModelTags.fromJson((jsonDecode("{\"tags\":[\"example string\"]}") as Map).cast<String, dynamic>())),
