      expect(
        mismatch(
          normal(actual),
          SdkUtils.decodeJson("{\"error\":\"example string\",\"import_job\":{\"bytes_done\":\"12345\",\"bytes_total\":\"12345\",\"completed_at\":\"2023-01-01T00:00:00Z\",\"created_at\":\"2023-01-01T00:00:00Z\",\"error_message\":\"example string\",\"error_step\":\"example string\",\"files_done\":123,\"files_total\":123,\"started_at\":\"2023-01-01T00:00:00Z\",\"status\":\"example string\",\"uuid\":\"123e4567-e89b-12d3-a456-426614174000\"},\"model\":{\"active_deployments\":[{\"created_at\":\"example string\",\"endpoints\":{\"private_endpoint_fqdn\":\"example string\",\"public_endpoint_fqdn\":\"example string\"},\"id\":\"example string\",\"name\":\"example name\",\"region_slug\":\"example string\",\"state\":\"example string\",\"updated_at\":\"2023-01-01\"}],\"architecture\":\"example string\",\"config_json\":{},\"context_length\":123,\"cost_estimate_per_month\":123,\"created_at\":\"2023-01-01T00:00:00Z\",\"description\":\"example string\",\"error_message\":\"example string\",\"file_count\":123,\"input_modalities\":[\"example string\"],\"license\":\"example string\",\"name\":\"example name\",\"output_modalities\":[\"example string\"],\"parameters\":\"12345\",\"source_ref\":{\"access_type\":\"ACCESS_TYPE_UNSPECIFIED\",\"bucket\":\"example string\",\"commit_sha\":\"example string\",\"hf_token\":\"example string\",\"prefix\":\"example string\",\"region\":\"example string\",\"repo_id\":\"123e4567-e89b-12d3-a456-426614174000\"},\"source_type\":\"SOURCE_TYPE_UNSPECIFIED\",\"status\":\"STATUS_UNSPECIFIED\",\"storage_region\":\"example string\",\"tags\":{\"tags\":[\"example string\"]},\"team_id\":\"12345\",\"total_size_bytes\":\"12345\",\"updated_at\":\"2023-01-01T00:00:00Z\",\"uuid\":\"123e4567-e89b-12d3-a456-426614174000\"},\"validation_steps\":[{\"error\":\"example string\",\"name\":\"example name\",\"passed\":true}]}"),
