    test("genaiUpdateAgent answers 401 with its declared error body", () async {
      SdkConfig.getConfig().baseUrl = '$baseUrl/__mockStatus/401';
      addTearDown(() => SdkConfig.getConfig().baseUrl = baseUrl);
      final SdkHttpError error;
      try {
        await sdk_methods_22.genaiUpdateAgent(
        config,
        uuid: (jsonDecode("\"\\\"123e4567-e89b-12d3-a456-426614174000\\\"\"") as String),
        agentLogInsightsEnabled: SdkPresent<bool>((jsonDecode("true") as bool)),
        allowedDomains: SdkPresent<List<String>>((jsonDecode("[\"example string\"]") as List).map((element) => (element as String)).toList()),
        anthropicKeyUuid: SdkPresent<String>((jsonDecode("\"\\\"12345678-1234-1234-1234-123456789012\\\"\"") as String)),
        clearMcpServers: SdkPresent<bool>((jsonDecode("true") as bool)),
        conversationLogsEnabled: SdkPresent<bool>((jsonDecode("true") as bool)),
        description: SdkPresent<String>((jsonDecode("\"\\\"My Agent Description\\\"\"") as String)),
        instruction: SdkPresent<String>((jsonDecode("\"\\\"You are an agent who thinks deeply about the world\\\"\"") as String)),
        k: SdkPresent<int>((jsonDecode("5") as num).toInt()),
        maxTokens: SdkPresent<int>((jsonDecode("100") as num).toInt()),
        mcpServers: SdkPresent<List<ApiMcpServer>>((jsonDecode("[{\"allowed_tools\":[\"example string\"],\"authorization\":\"example string\",\"headers\":{\"key\":\"example string\"},\"server_label\":\"example string\",\"server_url\":\"example string\"}]") as List).map((element) => ApiMcpServer.fromJson((element as Map).cast<String, dynamic>())).toList()),
        modelProviderKeyUuid: SdkPresent<String>((jsonDecode("\"\\\"12345678-1234-1234-1234-123456789012\\\"\"") as String)),
        modelRouterUuid: SdkPresent<String>((jsonDecode("\"\\\"12345678-1234-1234-1234-123456789012\\\"\"") as String)),
        modelUuid: SdkPresent<String>((jsonDecode("\"\\\"12345678-1234-1234-1234-123456789012\\\"\"") as String)),
        name: SdkPresent<String>((jsonDecode("\"\\\"My New Agent Name\\\"\"") as String)),
        openAiKeyUuid: SdkPresent<String>((jsonDecode("\"\\\"12345678-1234-1234-1234-123456789012\\\"\"") as String)),
        projectId: SdkPresent<String>((jsonDecode("\"\\\"12345678-1234-1234-1234-123456789012\\\"\"") as String)),
        provideCitations: SdkPresent<bool>((jsonDecode("true") as bool)),
        reasoningEffort: SdkPresent<String>((jsonDecode("\"\\\"low\\\"\"") as String)),
        retrievalMethod: SdkPresent<ApiRetrievalMethod>(ApiRetrievalMethod.fromJson(jsonDecode("\"RETRIEVAL_METHOD_UNKNOWN\"") as String)),
        routerPresetSlug: SdkPresent<String>((jsonDecode("\"\\\"general\\\"\"") as String)),
        tags: SdkPresent<List<String>>((jsonDecode("[\"example string\"]") as List).map((element) => (element as String)).toList()),
        temperature: SdkPresent<double>((jsonDecode("0.7") as num).toDouble()),
        thinkingTokenBudget: SdkPresent<int>((jsonDecode("123") as num).toInt()),
        topP: SdkPresent<double>((jsonDecode("0.9") as num).toDouble()),
        uuid_2: SdkPresent<String>((jsonDecode("\"\\\"12345678-1234-1234-1234-123456789012\\\"\"") as String)),
        webFetchEnabled: SdkPresent<bool>((jsonDecode("true") as bool)),
        webSearchEnabled: SdkPresent<bool>((jsonDecode("true") as bool)),
      );
        fail('did not raise its declared error');
      } on SdkHttpError catch (caught) {
        error = caught;
      }
      expect(error.statusCode, 401);
      expect(
        mismatch(normal(error.data), SdkUtils.decodeJson("{\"id\":\"unauthorized\",\"message\":\"Unable to authenticate you.\"}")),
        isNull,
      );
    });

