    test("genaiUpdateAgentFunction answers 401 with its declared error body", () async {
      SdkConfig.getConfig().baseUrl = '$baseUrl/__mockStatus/401';
      addTearDown(() => SdkConfig.getConfig().baseUrl = baseUrl);
      final SdkHttpError error;
      try {
        await sdk_methods_22.genaiUpdateAgentFunction(
        config,
        agentUuid: (jsonDecode("\"\\\"123e4567-e89b-12d3-a456-426614174000\\\"\"") as String),
        functionUuid: (jsonDecode("\"\\\"123e4567-e89b-12d3-a456-426614174000\\\"\"") as String),
        agentUuid_2: SdkPresent<String>((jsonDecode("\"\\\"12345678-1234-1234-1234-123456789012\\\"\"") as String)),
        description: SdkPresent<String>((jsonDecode("\"\\\"My Function Description\\\"\"") as String)),
        faasName: SdkPresent<String>((jsonDecode("\"\\\"my-function\\\"\"") as String)),
        faasNamespace: SdkPresent<String>((jsonDecode("\"\\\"default\\\"\"") as String)),
        functionName: SdkPresent<String>((jsonDecode("\"\\\"My Function\\\"\"") as String)),
        functionUuid_2: SdkPresent<String>((jsonDecode("\"\\\"12345678-1234-1234-1234-123456789012\\\"\"") as String)),
        inputSchema: SdkPresent<Map<String, dynamic>>(<String, dynamic>{}),
        outputSchema: SdkPresent<Map<String, dynamic>>(<String, dynamic>{}),
      );
        fail('did not raise its declared error');
      } on SdkHttpError catch (caught) {
        error = caught;
      }
      expect(error.statusCode, 401);
      expect(
        mismatch(normal(error.data), SdkUtils.decodeJson("{\"id\":\"unauthorized\",\"message\":\"Unable to authenticate you.\"}")),
        isNull,
      );
    });

